import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, sin } from 'three/tsl';
import { gsap } from 'gsap';

function hexToRgb(hex, fallback) {
  if (typeof hex !== 'string') return fallback;
  const value = hex.replace('#', '');
  if (!/^[0-9a-fA-F]{6}$/.test(value)) return fallback;
  return [
    parseInt(value.slice(0, 2), 16) / 255,
    parseInt(value.slice(2, 4), 16) / 255,
    parseInt(value.slice(4, 6), 16) / 255,
  ];
}

function colorNodeFromHex(hex, fallback) {
  const [r, g, b] = hexToRgb(hex, fallback);
  return vec3(r, g, b);
}

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;
  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {};

  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const root = new Group();
  root.name = 'pricing-title';

  const ownedGeometries = [];
  const ownedMaterials = [];
  const ownedTextures = [];
  const timelines = [];
  let cleaned = false;

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: true,
  });

  const backdropUv = uv();
  const topColor = colorNodeFromHex(ink, [0.086, 0.086, 0.114]);
  const bottomColor = colorNodeFromHex(surface, [0.043, 0.043, 0.063]);
  const accentColor = colorNodeFromHex(accent, [1, 0.165, 0.22]);

  const verticalBlend = smoothstep(0.04, 0.96, backdropUv.y);
  const baseGradient = mix(bottomColor, topColor, verticalBlend);

  const grainSignal = sin(
    backdropUv.x.mul(181.7).add(backdropUv.y.mul(263.1))
  ).mul(0.5).add(0.5);

  const engineeredGradient = mix(
    baseGradient,
    mix(baseGradient, accentColor, 0.018),
    grainSignal.mul(0.045)
  );

  backdropMaterial.colorNode = engineeredGradient;

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-stage';
  backdrop.position.z = -2.5;
  root.add(backdrop);

  ownedGeometries.push(backdropGeometry);
  ownedMaterials.push(backdropMaterial);

  const imageGeometry = new PlaneGeometry(6.4, 4.8);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: paper,
    transparent: true,
    opacity: 0.075,
    depthWrite: false,
  });
  const imageLayer = new Mesh(imageGeometry, imageMaterial);
  imageLayer.name = 'isolated-atlas-texture';
  imageLayer.position.z = -2.36;
  imageLayer.renderOrder = 1;
  root.add(imageLayer);

  ownedGeometries.push(imageGeometry);
  ownedMaterials.push(imageMaterial);

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (cleaned) {
        texture.dispose?.();
        return;
      }
      ownedTextures.push(texture);
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    });
  }

  const plateGeometry = new BoxGeometry(5.2, 0.025, 0.08);
  const plateMaterial = new MeshBasicNodeMaterial({
    color: ink,
  });
  const plate = new Mesh(plateGeometry, plateMaterial);
  plate.name = 'title-machined-plate';
  plate.position.set(0, -0.58, -0.05);
  plate.scale.set(1, 1, 1);
  root.add(plate);

  ownedGeometries.push(plateGeometry);
  ownedMaterials.push(plateMaterial);

  const signalGeometry = new BoxGeometry(0.72, 0.045, 0.1);
  const signalMaterial = new MeshBasicNodeMaterial({
    color: accent,
  });
  const signal = new Mesh(signalGeometry, signalMaterial);
  signal.name = 'signal-red-accent';
  signal.position.set(-2.23, -0.58, 0.02);
  signal.renderOrder = 3;
  root.add(signal);

  ownedGeometries.push(signalGeometry);
  ownedMaterials.push(signalMaterial);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: paper,
      align: item.typography?.align ?? 'center',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx,
    });

    textObject.name = `pricing-title-${item.role ?? 'headline'}`;
    textObject.position.set(0, 0.03, 0.12);
    textObject.renderOrder = 4;
    root.add(textObject);
  }

  const entrance = gsap.timeline({ paused: false });
  entrance.from(root.scale, {
    x: 0.96,
    y: 0.96,
    z: 0.96,
    duration: 0.7,
    ease: 'power3.out',
  });
  timelines.push(entrance);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    if (cleaned) return;
    cleaned = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    for (const texture of ownedTextures) {
      texture.dispose?.();
    }

    for (const material of ownedMaterials) {
      material.dispose?.();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    root.traverse((object) => {
      if (object !== root && object.parent) object.parent.remove(object);
    });
  };

  return root;
}
